const post = (base, body) => json(base, "/api/tasks", "POST", body);
const get = async (base, q) => { const r = await json(base, "/api/tasks" + q); return [r.status, await r.json()]; };

test("normaliza tags e valida due", () => withServer(async (base) => {
  const t = await (await post(base, { title: "a", tags: [" Casa ", "casa", "WORK"], due: "2024-02-29" })).json();
  assert.deepEqual(t.tags, ["casa", "work"]);
  assert.equal(t.due, "2024-02-29");
  for (const bad of [{ tags: ["  "] }, { tags: ["x".repeat(21)] }, { tags: "a" }, { tags: [1] }, { tags: ["1", "2", "3", "4", "5", "6"] },
    { due: "2023-02-29" }, { due: "2024-1-1" }, { due: 5 }, { title: "x".repeat(101) }])
    assert.equal((await post(base, { title: "t", ...bad })).status, 400, JSON.stringify(bad));
  assert.equal((await post(base, { title: "x".repeat(100), tags: ["a", "A", "b", "c", "d", "e"] })).status, 201);
}));

test("PATCH altera tags/due, limpa due; inválido não altera nada", () => withServer(async (base) => {
  const t = await (await post(base, { title: "a", due: "2030-01-01" })).json();
  const ok = await (await json(base, `/api/tasks/${t.id}`, "PATCH", { tags: [" X "], due: null })).json();
  assert.deepEqual([ok.tags, ok.due], [["x"], null]);
  assert.equal((await json(base, `/api/tasks/${t.id}`, "PATCH", { done: true, tags: ["y"], due: "nope" })).status, 400);
  const [, l] = await get(base, "");
  assert.deepEqual([l.items[0].done, l.items[0].tags], [false, ["x"]]);
}));

test("filtros, paginação e overdue", () => withServer(async (base) => {
  await post(base, { title: "1", tags: ["Casa"], due: "2000-01-01" });
  await post(base, { title: "2", tags: ["casa"], due: "2999-01-01" });
  const t3 = await (await post(base, { title: "3", due: "2000-01-01" })).json();
  await json(base, `/api/tasks/${t3.id}`, "PATCH", { done: true });
  const titles = (r) => r.items.map((t) => t.title);
  let [, r] = await get(base, "?tag=CASA");
  assert.deepEqual(titles(r), ["1", "2"]);
  [, r] = await get(base, "?overdue=true");
  assert.deepEqual(titles(r), ["1"]);
  [, r] = await get(base, "?done=true");
  assert.equal(r.total, 1);
  [, r] = await get(base, "?limit=2&page=2");
  assert.deepEqual([titles(r), r.page, r.limit, r.total], [["3"], 2, 2, 3]);
  [, r] = await get(base, "?tag=casa&limit=1&page=2");
  assert.deepEqual([titles(r), r.total], [["2"], 2]);
  for (const q of ["?page=0", "?page=x", "?limit=51", "?limit=0", "?done=yes", "?overdue=false", "?tag="])
    assert.equal((await get(base, q))[0], 400, q);
}));

