const list = document.getElementById("list");
const form = document.getElementById("form");
const titleInput = document.getElementById("title");
const tagFilter = document.getElementById("tagFilter");
const doneFilter = document.getElementById("doneFilter");
const prev = document.getElementById("prev");
const next = document.getElementById("next");
const pageInfo = document.getElementById("pageInfo");
const LIMIT = 10;
let page = 1;

async function load() {
  const q = new URLSearchParams({ page, limit: LIMIT });
  if (tagFilter.value.trim()) q.set("tag", tagFilter.value.trim());
  if (doneFilter.value) q.set("done", doneFilter.value);
  const res = await fetch("/api/tasks?" + q);
  if (!res.ok) return;
  const { items, total } = await res.json();
  const pages = Math.max(1, Math.ceil(total / LIMIT));
  if (page > pages) { page = pages; return load(); } // página ficou vazia após excluir/filtrar
  const today = new Date().toISOString().slice(0, 10);
  list.replaceChildren();
  for (const t of items) {
    const li = document.createElement("li");
    if (t.done) li.className = "done";
    const late = !t.done && t.due && t.due < today;
    if (late) li.classList.add("overdue");
    const box = document.createElement("input");
    box.type = "checkbox"; box.checked = t.done;
    box.addEventListener("change", async () => {
      await fetch(`/api/tasks/${t.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ done: box.checked }) });
      load();
    });
    const text = document.createElement("span");
    text.textContent = t.title;
    li.append(box, text);
    for (const tag of t.tags) {
      const b = document.createElement("small");
      b.className = "tag"; b.textContent = "#" + tag;
      li.append(b);
    }
    if (t.due) {
      const d = document.createElement("small");
      d.textContent = (late ? "Atrasada · " : "Prazo: ") + t.due;
      li.append(d);
    }
    const del = document.createElement("button");
    del.textContent = "Excluir";
    del.addEventListener("click", async () => { await fetch(`/api/tasks/${t.id}`, { method: "DELETE" }); load(); });
    li.append(del);
    list.append(li);
  }
  pageInfo.textContent = `Página ${page} de ${pages} (${total})`;
  prev.disabled = page <= 1;
  next.disabled = page >= pages;
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();
  await fetch("/api/tasks", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ title: titleInput.value }) });
  titleInput.value = "";
  load();
});
const refilter = () => { page = 1; load(); };
tagFilter.addEventListener("input", refilter);
doneFilter.addEventListener("change", refilter);
prev.addEventListener("click", () => { page--; load(); });
next.addEventListener("click", () => { page++; load(); });
load();

